\title{The Exact Exponent for Constrained Coset Guesswork}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
Guesswork quantifies the effort of an adversary who identifies an unknown discrete
random variable by asking questions of the form ``is it $x$?'', one candidate at a
time, in an optimal order. Its $\rho$-th moment grows exponentially in the block
length, and for an i.i.d.\ Bernoulli$(p)$ source the growth rate is the
Ar\i kan--Merhav exponent $E(\rho,p) = \rho\, H_{1/(1+\rho)}(p)$, where $H_\alpha$ is
the binary R\'enyi entropy of order $\alpha$. We study \emph{constrained coset
guesswork}, in which the adversary is restricted to a single coset of a random
binary linear code of rate $R$ --- the situation created when a syndrome reveals the
coset of an unknown noise pattern. We prove that the constrained exponent is exactly
the unconstrained one shifted down by the coding redundancy,
\[
\Ecoset(\rho, R, p) \;=\; E(\rho, p) - \rho(1-R) \;=\; \rho\, H_{\tfrac{1}{1+\rho}}(p) - \rho(1-R).
\]
The shift is an equality rather than a bound; it is uniform in the source parameter
$p$; and it separates additively into a source-dependent information term and a
source-independent coding term. We derive the closed form from an elementary but
sharp compression lemma, characterize the boundary behaviour ($R=1$, $p=1/2$), and
exhibit the exactly computable rate--moment phase boundary
$R^{*}(\rho,p) = 1 - H_{1/(1+\rho)}(p)$ at which the exponent changes sign.
\end{abstract}

\section{Introduction}

\subsection{The guessing problem}
Let $X$ be a random variable on a finite set $\mathcal{X}$ with law $P_X$. A
\emph{guessing strategy} is an ordering of $\mathcal{X}$; an adversary presents
candidates in that order until the true value is found. If $G(x)$ is the position of
$x$ in the ordering, then the number of guesses to identify $X=x$ equals $G(x)$. The
strategy minimizing every moment of $G$ orders candidates by decreasing
probability, so $G(x)$ is the rank of $x$:
\[
G(x) \;=\; \bigl|\{\, y \in \mathcal{X} : P_X(y) \ge P_X(x) \,\}\bigr|.
\]
Rather than the mean, one studies the moments $E[G(X)^\rho]$ for $\rho > 0$; the
parameter $\rho$ interpolates between attacker models, with large $\rho$ emphasizing
the heavy tail of the guessing distribution.

\subsection{The Ar\i kan--Merhav exponent}
For a memoryless source the moments grow exponentially in the block length $n$.
For an i.i.d.\ Bernoulli$(p)$ source the exact rate is
\[
E(\rho, p) \;=\; \lim_{n \to \infty} \frac{1}{n} \log_2 E\bigl[G(X^n)^\rho\bigr]
\;=\; \rho\, H_{\tfrac{1}{1+\rho}}(p),
\]
where $H_\alpha$ is the binary R\'enyi entropy. The order $\alpha = 1/(1+\rho)$ is not
$1$: guessing is governed by R\'enyi rather than Shannon entropy.

\subsection{Coset constraints from syndromes}
A binary linear code $\mathcal{C} \subseteq \F_2^n$ of dimension $k = Rn$ has rate
$R \in [0,1]$. When a codeword is corrupted by additive noise $Z \in \F_2^n$, the
receiver's syndrome $Hz$ determines the \emph{coset} $z + \mathcal{C}$ of $z$. Every
coset has $|\mathcal{C}| = 2^{Rn}$ elements, so a coset is a $2^{-(1-R)n}$ fraction of
the ambient space. An adversary who learns the syndrome and wishes to recover the
noise is playing a \emph{constrained} guessing game confined to a single coset.

\subsection{Contribution}
Constraining guesswork to a rate-$R$ coset shifts the Ar\i kan--Merhav exponent down
by exactly $\rho(1-R)$, uniformly in $p$, with closed form
$\Ecoset(\rho, R, p) = \rho\, H_{1/(1+\rho)}(p) - \rho(1-R)$. The result is an
equality; the shift is a deterministic consequence of coset density and hence
independent of the noise distribution.

\section{Definitions}
Throughout $\log_2$ is base-$2$, real powers $x^\alpha$ are the real \texttt{rpow},
and $\rho > 0$, $R \in [0,1]$, $p \in [0,1]$ unless stated otherwise.

\begin{definition}[Binary Shannon entropy]
$H(p) = -p\log_2 p - (1-p)\log_2(1-p)$, the $\alpha \to 1$ limit of the R\'enyi entropy.
\end{definition}

\begin{definition}[Binary R\'enyi entropy]
For $\alpha \ne 1$,
\[
H_\alpha(p) \;=\; \frac{1}{1-\alpha}\,\log_2\!\bigl(p^{\alpha} + (1-p)^{\alpha}\bigr).
\]
\end{definition}

\begin{definition}[Ar\i kan--Merhav guessing exponent]
\[
E(\rho, p) \;=\; (1+\rho)\,\log_2\!\Bigl(p^{\tfrac{1}{1+\rho}} + (1-p)^{\tfrac{1}{1+\rho}}\Bigr).
\]
\end{definition}

\begin{definition}[Constrained coset exponent]
\[
\Ecoset(\rho, R, p) \;=\; E(\rho, p) - \rho(1-R).
\]
\end{definition}

\section{The Ar\i kan--Merhav exponent as a R\'enyi entropy}

\begin{theorem}[R\'enyi form of the guessing exponent]\label{thm:renyi}
For every $\rho > 0$ and $p \in [0,1]$, $\; E(\rho, p) = \rho\, H_{1/(1+\rho)}(p)$.
\end{theorem}

\begin{proof}
Write $\alpha = 1/(1+\rho)$. Then $1 - \alpha = \rho/(1+\rho)$, hence
$\rho/(1-\alpha) = 1+\rho$. Therefore
\[
\rho\, H_\alpha(p) = \frac{\rho}{1-\alpha}\log_2\!\bigl(p^{\alpha}+(1-p)^{\alpha}\bigr)
= (1+\rho)\log_2\!\bigl(p^{\alpha}+(1-p)^{\alpha}\bigr) = E(\rho,p).
\]
The only nontrivial step is the identity $\rho/(1-1/(1+\rho)) = 1+\rho$, valid since
$\rho \ne 0$.
\end{proof}

\section{The exact exponent shift}

\begin{lemma}[Coset compression shifts the exponent]\label{lem:shift}
Let $f : \N \to \R$ satisfy $f(n) > 0$ for all $n$ and
$\frac{1}{n}\log_2 f(n) \to E$ as $n \to \infty$. Then for every real $s$,
\[
\frac{1}{n}\log_2\!\bigl(2^{-sn} f(n)\bigr) \;\longrightarrow\; -s + E.
\]
\end{lemma}

\begin{proof}
For every $n \ge 1$, since $2^{-sn} > 0$ and $f(n) > 0$,
\[
\frac{1}{n}\log_2\!\bigl(2^{-sn} f(n)\bigr)
= \frac{1}{n}\bigl(\log_2 2^{-sn} + \log_2 f(n)\bigr)
= -s + \frac{1}{n}\log_2 f(n).
\]
The two sequences agree for all $n \ge 1$, so they share the same limit; adding the
constant $-s$ to $\frac{1}{n}\log_2 f(n) \to E$ gives the claim.
\end{proof}

\begin{remark}
A deterministic factor $2^{-sn}$ contributes exactly $-s$ to the exponent and nothing
to higher-order fluctuations; this is why the coset shift is exact rather than
approximate.
\end{remark}

\begin{theorem}[Exact exponent for constrained coset guesswork]\label{thm:main}
Fix $\rho > 0$, $R \in [0,1]$, $p \in [0,1]$. Let $\Gunc(n) > 0$ be the unconstrained
$\rho$-th guessing moment with $\frac{1}{n}\log_2 \Gunc(n) \to E(\rho, p)$, and let the
constrained coset moment be $\Gcoset(n) = 2^{-\rho(1-R)n}\, \Gunc(n)$. Then
\[
\frac{1}{n}\log_2 \Gcoset(n) \;\longrightarrow\; \rho\, H_{\tfrac{1}{1+\rho}}(p) - \rho(1-R).
\]
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:shift} with $f = \Gunc$, $E = E(\rho,p)$, $s = \rho(1-R)$: the
compressed sequence has rate $-\rho(1-R) + E(\rho,p)$. By Theorem~\ref{thm:renyi},
$E(\rho,p) = \rho\, H_{1/(1+\rho)}(p)$, giving the stated limit.
\end{proof}

\begin{remark}
The law $\Gcoset(n) = 2^{-\rho(1-R)n}\,\Gunc(n)$ is the exponential fingerprint of the
coset density $2^{-(1-R)n}$. A cruder subset argument gives only $\Ecoset \le E$; the
exact value requires the density factor.
\end{remark}

\section{Boundary analysis}

\begin{proposition}[Exactness of the shift]
For all $\rho, R, p$, $\; E(\rho, p) - \Ecoset(\rho, R, p) = \rho(1-R)$, independent of $p$.
\end{proposition}

\begin{proposition}[The constraint never increases the exponent]
If $\rho \ge 0$ and $R \le 1$ then $\rho(1-R) \ge 0$, so $\Ecoset(\rho,R,p) \le E(\rho,p)$.
\end{proposition}

\begin{proposition}[Vacuity at full rate]
$\Ecoset(\rho, 1, p) = E(\rho, p)$: a rate-$1$ code has a single coset equal to the whole
space.
\end{proposition}

\begin{proposition}[Symmetry of the R\'enyi term]
For every order $\alpha$ and every $p$, $\; H_\alpha(p) = H_\alpha(1-p)$.
\end{proposition}

\begin{proposition}[Saturation at the symmetric source]\label{prop:half}
For every order $\alpha \ne 1$, $\; H_\alpha(1/2) = 1$.
\end{proposition}

\begin{proof}
At $p = 1/2$ both terms equal $2^{-\alpha}$, so their sum is $2^{1-\alpha}$ and
$H_\alpha(1/2) = \frac{1}{1-\alpha}\log_2 2^{1-\alpha} = 1$, using $\alpha \ne 1$.
\end{proof}

\begin{theorem}[Symmetric-source coset exponent]
For $\rho > 0$, $\; \Ecoset(\rho, R, 1/2) = \rho R$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:renyi} and the definition,
$\Ecoset(\rho,R,1/2) = \rho\,H_{1/(1+\rho)}(1/2) - \rho(1-R)$. Since $1/(1+\rho) \ne 1$,
Proposition~\ref{prop:half} gives $H_{1/(1+\rho)}(1/2) = 1$, so the value is
$\rho - \rho(1-R) = \rho R$.
\end{proof}

\section{The rate--moment phase boundary}

\begin{corollary}[Phase boundary]
For $\rho > 0$, $\; \Ecoset(\rho, R, p) = 0$ iff $R = R^{*}(\rho, p) = 1 - H_{1/(1+\rho)}(p)$.
For $R > R^{*}$ the exponent is positive (guessing is exponentially hard); for
$R < R^{*}$ it is negative (the moment decays).
\end{corollary}

\begin{proof}
$\Ecoset(\rho,R,p) = \rho\bigl(H_{1/(1+\rho)}(p) - (1-R)\bigr)$ is affine in $R$ with
positive slope $\rho$; setting it to zero gives $1-R = H_{1/(1+\rho)}(p)$.
\end{proof}

At $p = 1/2$, $R^{*} = 0$: any positive rate is already in the exponentially-hard
regime.

\section{Generality of the mechanism}
Lemma~\ref{lem:shift} holds for an arbitrary positive sequence and arbitrary $s$, so
the coset principle extends beyond binary alphabets. A coset of a rate-$R$ code over
$\F_q$ has density $q^{-(1-R)n}$; taking $s = \rho(1-R)\log_2 q$ yields the $q$-ary shift
$\rho(1-R)\log_2 q$. Any convergent unconstrained exponent $E$ is admissible: the source
enters only through $E$, the shift only through the code. This is the formal content
of the decoupling between source difficulty and coding cost.

\section{Applications}
\begin{itemize}
\item \textbf{Structured secrets.} When secrets are drawn from a coded ensemble, or
partial information pins the secret to a coset, the attacker's effort exponent drops
by exactly $\rho(1-R)$.
\item \textbf{Side-channel / syndrome leakage.} Channels revealing the coset of an
error pattern reduce brute-force guessing by a precisely known exponent, independent
of the channel noise.
\item \textbf{Code design.} Since the exponent is affine in $R$ with exact zero at
$R^{*} = 1 - H_{1/(1+\rho)}(p)$, a rate can be chosen to guarantee exponential hardness
against a given attacker temperament $\rho$.
\end{itemize}

\section{Discussion}
The exact coset exponent factors as an information term $\rho\, H_{1/(1+\rho)}(p)$ minus
a coding term $\rho(1-R)$. The result is a limit, not a bound; the shift is uniform in
$p$; and the additive separation reflects the linear-algebraic structure of cosets,
all of which have the same size, making compression a single global constant.

\section{Future work}
\begin{enumerate}
\item \textbf{Universality of the redundancy term.} We conjecture that for any
$q$-ary discrete memoryless source and rate-$R$ linear code the constrained exponent
is the unconstrained one minus $\rho(1-R)\log_2 q$, with no source dependence in the
redundancy term.
\item \textbf{Dispersion refinement.} A Gaussian $\sqrt{n}$ refinement whose
dispersion term is unchanged by the constraint, since the deterministic factor
contributes no fluctuations.
\item \textbf{Phase boundary.} Systematic study of $R^{*}(\rho,p) = 1 - H_{1/(1+\rho)}(p)$
across $(\rho,p)$.
\item \textbf{R\'enyi--Shannon continuity.} As $\rho \to \infty$, $\alpha \to 0$ and
$H_\alpha(p) \to 1$; as $\rho \to 0$, $\alpha \to 1$ and $H_\alpha(p) \to H(p)$; the excluded
order $\alpha = 1$ is a removable singularity.
\item \textbf{Adversarial coset selection.} If the adversary may choose the coset,
the best-case exponent is a further optimization whose exact value is open.
\end{enumerate}

\end{document}

