import math

def binary_renyi_entropy(alpha: float, p: float) -> float:
    """H_alpha(p) = (1/(1-alpha)) log2(p^alpha + (1-p)^alpha), alpha != 1."""
    powa = lambda x: 0.0 if x == 0.0 else x ** alpha
    return (1.0 / (1.0 - alpha)) * math.log2(powa(p) + powa(1.0 - p))

def am_exponent(rho: float, p: float) -> float:
    """Arikan-Merhav exponent (1+rho) log2(p^b + (1-p)^b), b = 1/(1+rho)."""
    b = 1.0 / (1.0 + rho)
    powb = lambda x: 0.0 if x == 0.0 else x ** b
    return (1.0 + rho) * math.log2(powb(p) + powb(1.0 - p))

def am_via_renyi(rho: float, p: float) -> float:
    return rho * binary_renyi_entropy(1.0 / (1.0 + rho), p)

if __name__ == "__main__":
    for rho, p in [(1.0, 0.1), (2.0, 0.25), (0.5, 0.4), (3.0, 0.05)]:
        a, b = am_exponent(rho, p), am_via_renyi(rho, p)
        print(f"rho={rho} p={p}: computational={a:.10f} renyi={b:.10f} diff={abs(a-b):.2e}")

import math

def am_exponent(rho: float, p: float) -> float:
    b = 1.0 / (1.0 + rho)
    powb = lambda x: 0.0 if x == 0.0 else x ** b
    return (1.0 + rho) * math.log2(powb(p) + powb(1.0 - p))

def constrained_exponent(rho: float, R: float, p: float) -> float:
    """E_coset(rho,R,p) = E_AM(rho,p) - rho*(1-R)."""
    return am_exponent(rho, p) - rho * (1.0 - R)

if __name__ == "__main__":
    # The gap between unconstrained and constrained exponents is rho*(1-R),
    # independent of the source parameter p.
    for rho, R in [(1.0, 0.5), (2.0, 0.75), (3.0, 0.5)]:
        print(f"rho={rho} R={R}:")
        for p in [0.05, 0.2, 0.4, 0.5]:
            gap = am_exponent(rho, p) - constrained_exponent(rho, R, p)
            print(f"  p={p}: gap={gap:.8f} (predicted rho*(1-R)={rho*(1-R):.8f})")

import itertools, math

def prob(bits, p):
    ones = sum(bits)
    return (p ** ones) * ((1.0 - p) ** (len(bits) - ones))

def unconstrained_moment(n: int, p: float, rho: float) -> float:
    vs = sorted(itertools.product((0, 1), repeat=n), key=lambda v: prob(v, p), reverse=True)
    return sum(prob(v, p) * (r ** rho) for r, v in enumerate(vs, 1))

def coset_moment(n: int, p: float, rho: float, syndrome: int) -> float:
    """Conditional guessing moment inside a coset of the parity code (rate (n-1)/n)."""
    coset = [v for v in itertools.product((0, 1), repeat=n) if sum(v) % 2 == syndrome]
    w = [prob(v, p) for v in coset]
    z = sum(w)
    order = sorted(range(len(coset)), key=lambda i: w[i], reverse=True)
    return sum((w[i] / z) * (r ** rho) for r, i in enumerate(order, 1))

if __name__ == "__main__":
    rho, p = 1.0, 0.2
    for n in range(3, 13):
        R = (n - 1) / n
        e_unc = math.log2(unconstrained_moment(n, p, rho)) / n
        e_cos = math.log2(coset_moment(n, p, rho, 0)) / n
        print(f"n={n:2d} R={R:.3f} shift={e_unc-e_cos:.4f} predicted={rho*(1-R):.4f}")

import math

def binary_renyi_entropy(alpha: float, p: float) -> float:
    powa = lambda x: 0.0 if x == 0.0 else x ** alpha
    return (1.0 / (1.0 - alpha)) * math.log2(powa(p) + powa(1.0 - p))

def phase_boundary_rate(rho: float, p: float) -> float:
    """R*(rho,p) = 1 - H_{1/(1+rho)}(p): the rate where E_coset changes sign."""
    return 1.0 - binary_renyi_entropy(1.0 / (1.0 + rho), p)

def constrained_exponent(rho: float, R: float, p: float) -> float:
    return rho * (binary_renyi_entropy(1.0 / (1.0 + rho), p) - (1.0 - R))

if __name__ == "__main__":
    for rho in [0.5, 1.0, 2.0, 4.0]:
        for p in [0.05, 0.1, 0.25, 0.5]:
            Rs = phase_boundary_rate(rho, p)
            print(f"rho={rho} p={p}: R*={Rs:+.5f} E(R*)={constrained_exponent(rho, Rs, p):.2e}")

