function EMPIRICAL_COSET_EXPONENT(n, p, rho, syndrome):
    coset <- [ x in {0,1}^n : sum(x) mod 2 == syndrome ]
    w[i]  <- Bernoulli_p_probability(coset[i])  for each i
    Z     <- sum(w)
    order <- indices of coset sorted by w descending
    M <- 0
    for rank, i in enumerate(order, start=1):
        M <- M + (w[i]/Z) * rank^rho
    return (1/n) * log2(M)

